import { customModelMeta } from "@posthog/shared";
import { describe, expect, it } from "vitest";
import {
  estimateUncachedInputCost,
  modelCostInfo,
  modelCostMultiplier,
  modelListPrice,
  toModelPickerOption,
} from "./modelPricing";

describe("modelPricing", () => {
  it.each([
    // The baseline anchors the scale; an exact ratio carries no ≈; diverging
    // input/output ratios earn one; sub-1 multipliers keep two decimals.
    ["claude-sonnet-5", "1×"],
    ["claude-opus-5", "2.5×"],
    ["gpt-5.5", "≈2.8×"],
    ["gpt-6-astra", "5×"],
    ["deepseek-ai/deepseek-v4-flash-0731", "≈0.05×"],
    ["zai-org/glm-5.3-flash", "≈0.06×"],
    // A picker hands back whichever form the gateway served.
    ["anthropic/claude-opus-5", "2.5×"],
    ["openai/gpt-6-sol", "1×"],
  ] as const)("%s -> %s", (modelId, expected) => {
    expect(modelCostInfo(modelId)?.multiplierLabel).toBe(expected);
  });

  it.each([
    // Absent from the catalog, then in it with no published price.
    "totally-unknown-model",
    "gpt-5",
  ] as const)("%s carries no price, so no wrong chip renders", (modelId) => {
    expect(modelCostInfo(modelId)).toBeNull();
    expect(modelListPrice(modelId)).toBeNull();
  });

  it("keeps an unpriced gateway model in the picker instead of throwing", () => {
    expect(
      toModelPickerOption({
        value: "future-gateway-model",
        name: "Future gateway model",
      }),
    ).toMatchObject({ kind: "unpriced", name: "Future gateway model" });

    expect(
      toModelPickerOption({
        value: "local-model",
        name: "Local model",
        _meta: customModelMeta(),
      }),
    ).toMatchObject({ kind: "custom" });
  });

  it("ranks models by the numeric multiplier the chips state", () => {
    const opus = modelCostMultiplier("claude-opus-5");
    const sonnet = modelCostMultiplier("claude-sonnet-5");
    expect(sonnet).toBe(1);
    expect(opus).toBe(2.5);
    expect(modelCostMultiplier("totally-unknown-model")).toBeNull();
  });

  it("carries the exact rates for tooltips", () => {
    // A sub-dollar rate exercises the two-decimal formatting the catalog does.
    expect(modelCostInfo("deepseek-ai/deepseek-v4-flash-0731")?.summary).toBe(
      "Input $0.13 · Output $0.26 per 1M tokens",
    );
  });

  it.each([
    ["gpt-5.6-terra", 100_000, 0.25],
    ["claude-sonnet-5", 50_000, 0.1],
    ["unknown-model", 100_000, null],
    ["claude-opus-5", 0, null],
  ] as const)(
    "estimates uncached input cost for %s with %s tokens",
    (modelId, tokens, expected) => {
      expect(estimateUncachedInputCost(modelId, tokens)).toBe(expected);
    },
  );
});

// The gateway pins the contract rates these models bill at, and the catalog
// this file reads claims to mirror them. In the monorepo the gateway file is
// six directories up; a standalone desktop checkout skips the comparison.
const MONOREPO_ROOT_RELATIVE = "../../../../../..";
const MONOREPO_SENTINEL_RELATIVE = `${MONOREPO_ROOT_RELATIVE}/pyproject.toml`;
const GATEWAY_OVERRIDES_RELATIVE = `${MONOREPO_ROOT_RELATIVE}/services/llm-gateway/src/llm_gateway/rate_limiting/model_cost_overrides.py`;

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function gatewayRate(
  source: string,
  block: string,
  key: string,
): number | null {
  const b = escapeRegExp(block);
  // The gateway holds rates in two shapes: a top-level `NAME = { ... }`
  // constant (the Baseten/Kimi models) and a quoted `"model-id": { ... }`
  // entry in the overrides dict (Fable and the GPT-5.6 models).
  const blockMatch = source.match(
    new RegExp(`(?:"${b}"\\s*:|${b}[^=\\n]*=)\\s*\\{([\\s\\S]*?)\\}`),
  );
  if (!blockMatch?.[1]) return null;
  const rate = blockMatch[1].match(
    new RegExp(`"${escapeRegExp(key)}":\\s*([0-9][0-9_.e-]*)`),
  );
  return rate?.[1] ? Number(rate[1].replaceAll("_", "")) : null;
}

describe("contract rates match the gateway's pinned table", () => {
  it.each([
    ["moonshotai/kimi-k3", "KIMI_K3_COST"],
    ["zai-org/glm-5.3", "BASETEN_GLM_COST"],
    ["zai-org/glm-5.3-flash", "BASETEN_GLM53_FLASH_COST"],
    ["deepseek-ai/deepseek-v4-flash-0731", "BASETEN_DEEPSEEK_COST"],
    ["claude-fable-5", "claude-fable-5"],
    ["gpt-5.6-sol", "gpt-5.6-sol"],
    ["gpt-5.6-terra", "gpt-5.6-terra"],
    ["gpt-5.6-luna", "gpt-5.6-luna"],
    ["gpt-6-astra", "gpt-6-astra"],
  ] as const)("%s", async (modelId, block) => {
    // A dynamic import keeps the pure-layer lint honest: only this test
    // touches the filesystem, and only to read the gateway's table.
    const { access, readFile } = await import("node:fs/promises");
    try {
      await access(new URL(MONOREPO_SENTINEL_RELATIVE, import.meta.url));
    } catch {
      // Not the monorepo, so there is no gateway table to compare against.
      return;
    }
    // In the monorepo the gateway file must exist: a read failure here means
    // it moved, and the mirror claim above needs its path updated.
    const gateway = await readFile(
      new URL(GATEWAY_OVERRIDES_RELATIVE, import.meta.url),
      "utf-8",
    );
    const price = modelListPrice(modelId);
    const input = gatewayRate(gateway, block, "input_cost_per_token");
    const output = gatewayRate(gateway, block, "output_cost_per_token");
    expect(input).not.toBeNull();
    expect(output).not.toBeNull();
    expect(price?.inputPerMtok).toBeCloseTo((input ?? 0) * 1e6, 6);
    expect(price?.outputPerMtok).toBeCloseTo((output ?? 0) * 1e6, 6);
  });
});

import { register } from 'prom-client'

import { RedisV2 } from '~/common/redis/redis-v2'

import { CyclotronJobInvocationHogFunction } from '../../types'
import { EmailValidationService, MAX_LOCAL_CACHE_DOMAINS } from './email-validation.service'

const mockResolveMx = jest.fn()
const mockResolve4 = jest.fn()
const mockResolve6 = jest.fn()

jest.mock('node:dns/promises', () => ({
    Resolver: jest.fn().mockImplementation(() => ({
        resolveMx: mockResolveMx,
        resolve4: mockResolve4,
        resolve6: mockResolve6,
    })),
}))

const dnsError = (code: string): NodeJS.ErrnoException => Object.assign(new Error(code), { code })

const emailInvocation = (email: unknown, teamId = 2): CyclotronJobInvocationHogFunction =>
    ({
        teamId,
        id: 'inv-1',
        functionId: 'flow-1',
        state: { actionId: 'act-1', globals: { inputs: { email: { to: { email } } } } },
    }) as any

const emailAction = { type: 'function_email', id: 'act-1' } as any

describe('EmailValidationService', () => {
    let service: EmailValidationService

    beforeEach(() => {
        jest.clearAllMocks()
        // Default to a healthy domain so tests only override what they exercise.
        mockResolveMx.mockResolvedValue([{ exchange: 'mx.example.com', priority: 10 }])
        mockResolve4.mockResolvedValue(['1.2.3.4'])
        mockResolve6.mockResolvedValue([])
        service = new EmailValidationService(null)
    })

    describe('gating', () => {
        it('does not validate (returns null, no DNS) for non-email actions', async () => {
            const reason = await service.getSkipReason(emailInvocation('x@dead.invalid'), {
                type: 'function_sms',
                id: 'act-1',
            } as any)
            expect(reason).toBeNull()
            expect(mockResolveMx).not.toHaveBeenCalled()
        })

        it('records the per-team skip metric when blocking', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve4.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve6.mockRejectedValue(dnsError('ENOTFOUND'))

            const reason = await service.getSkipReason(emailInvocation('x@dead.invalid', 3), emailAction)

            expect(reason).toContain('no reachable mail servers')
            const metric = await register.getSingleMetric('cdp_email_mx_skipped_total')!.get()
            expect(metric.values).toContainEqual(
                expect.objectContaining({ labels: { team_id: '3', reason: 'invalid_domain' } })
            )
        })
    })

    describe('syntax validation', () => {
        it.each([
            ['missing @', 'not-an-email'],
            ['empty local part', '@example.com'],
            ['no domain dot', 'user@localhost'],
            ['whitespace', 'user @example.com'],
            ['double @', 'a@b@example.com'],
        ])('blocks %s without a DNS lookup', async (_label, email) => {
            const reason = await service.getSkipReason(emailInvocation(email), emailAction)
            expect(reason).toContain('not a valid email address')
            expect(mockResolveMx).not.toHaveBeenCalled()
        })

        it.each([
            ['missing recipient', undefined],
            ['empty string', ''],
            ['non-string', 12345],
        ])('leaves %s for the existing send path (returns null)', async (_label, email) => {
            const reason = await service.getSkipReason(emailInvocation(email), emailAction)
            expect(reason).toBeNull()
            expect(mockResolveMx).not.toHaveBeenCalled()
        })
    })

    describe('domain deliverability', () => {
        it('allows a domain with MX records', async () => {
            mockResolveMx.mockResolvedValue([{ exchange: 'aspmx.l.google.com', priority: 1 }])
            expect(await service.getSkipReason(emailInvocation('user@gmail.com'), emailAction)).toBeNull()
        })

        it('resolves internationalized domains via their punycode form', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve4.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve6.mockRejectedValue(dnsError('ENOTFOUND'))

            const reason = await service.getSkipReason(emailInvocation('user@bücher.example'), emailAction)

            // The unicode form would error at the resolver (bypassing validation); the
            // punycode form gets a real verdict — here, a definitive block.
            expect(mockResolveMx).toHaveBeenCalledWith('xn--bcher-kva.example')
            expect(reason).toContain('no reachable mail servers')
        })

        it('allows a domain with no MX but an A record (RFC 5321 implicit MX)', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENODATA'))
            mockResolve4.mockResolvedValue(['93.184.216.34'])
            expect(await service.getSkipReason(emailInvocation('user@example.com'), emailAction)).toBeNull()
        })

        it('allows a domain with no MX or A but an AAAA record', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENODATA'))
            mockResolve4.mockRejectedValue(dnsError('ENODATA'))
            mockResolve6.mockResolvedValue(['2606:2800:220:1:248:1893:25c8:1946'])
            expect(await service.getSkipReason(emailInvocation('user@example.com'), emailAction)).toBeNull()
        })

        it('blocks a domain with no MX and no address records', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENODATA'))
            mockResolve4.mockRejectedValue(dnsError('ENODATA'))
            mockResolve6.mockRejectedValue(dnsError('ENODATA'))
            expect(await service.getSkipReason(emailInvocation('user@example.com'), emailAction)).toContain(
                'no reachable mail servers'
            )
        })

        it('blocks a non-existent domain (NXDOMAIN)', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve4.mockRejectedValue(dnsError('ENOTFOUND'))
            mockResolve6.mockRejectedValue(dnsError('ENOTFOUND'))
            expect(await service.getSkipReason(emailInvocation('user@does-not-exist.invalid'), emailAction)).toContain(
                'no reachable mail servers'
            )
        })

        it('blocks a domain that publishes a null MX (RFC 7505) without an A-record fallback', async () => {
            mockResolveMx.mockResolvedValue([{ exchange: '', priority: 0 }])
            expect(await service.getSkipReason(emailInvocation('user@no-mail.example'), emailAction)).toContain(
                'no reachable mail servers'
            )
            expect(mockResolve4).not.toHaveBeenCalled()
        })
    })

    describe('fail-open on transient DNS errors', () => {
        it.each([['ESERVFAIL'], ['ETIMEOUT'], ['EREFUSED'], ['ECONNREFUSED']])(
            'allows the send when the MX lookup fails with %s',
            async (code) => {
                mockResolveMx.mockRejectedValue(dnsError(code))
                expect(await service.getSkipReason(emailInvocation('user@flaky.example'), emailAction)).toBeNull()
            }
        )

        it('allows the send when the A-record fallback lookup is transiently unavailable', async () => {
            mockResolveMx.mockRejectedValue(dnsError('ENODATA'))
            mockResolve4.mockRejectedValue(dnsError('ESERVFAIL'))
            expect(await service.getSkipReason(emailInvocation('user@flaky.example'), emailAction)).toBeNull()
        })

        it('backs off briefly after a transient failure, then re-resolves instead of freezing the verdict', async () => {
            const now = Date.now()
            const nowSpy = jest.spyOn(Date, 'now').mockReturnValue(now)
            try {
                mockResolveMx.mockRejectedValueOnce(dnsError('ETIMEOUT'))
                expect(await service.getSkipReason(emailInvocation('user@flaky.example'), emailAction)).toBeNull()

                // Within the backoff window: still allowed, but without paying another slow lookup.
                expect(await service.getSkipReason(emailInvocation('user@flaky.example'), emailAction)).toBeNull()
                expect(mockResolveMx).toHaveBeenCalledTimes(1)

                // Past the window: DNS is consulted again, so the unknown verdict isn't frozen.
                nowSpy.mockReturnValue(now + 61_000)
                mockResolveMx.mockResolvedValue([{ exchange: 'mx.flaky.example', priority: 10 }])
                expect(await service.getSkipReason(emailInvocation('user@flaky.example'), emailAction)).toBeNull()
                expect(mockResolveMx).toHaveBeenCalledTimes(2)
            } finally {
                nowSpy.mockRestore()
            }
        })
    })

    describe('per-domain caching', () => {
        it('resolves each domain once and serves repeats from the in-process cache', async () => {
            mockResolveMx.mockResolvedValue([{ exchange: 'mx.example.com', priority: 10 }])
            for (let i = 0; i < 5; i++) {
                await service.getSkipReason(emailInvocation(`user${i}@example.com`), emailAction)
            }
            expect(mockResolveMx).toHaveBeenCalledTimes(1)
        })

        it('coalesces concurrent lookups for the same domain into a single DNS query', async () => {
            let resolveLookup: (records: unknown[]) => void = () => {}
            mockResolveMx.mockReturnValue(new Promise((resolve) => (resolveLookup = resolve)))

            const inFlight = Promise.all(
                Array.from({ length: 50 }, (_, i) =>
                    service.getSkipReason(emailInvocation(`user${i}@example.com`), emailAction)
                )
            )
            resolveLookup([{ exchange: 'mx.example.com', priority: 10 }])
            const reasons = await inFlight

            expect(mockResolveMx).toHaveBeenCalledTimes(1)
            expect(reasons.every((r) => r === null)).toBe(true)
        })

        it('evicts the oldest domain once the cache is full instead of growing unbounded', async () => {
            for (let i = 0; i <= MAX_LOCAL_CACHE_DOMAINS; i++) {
                await service.getSkipReason(emailInvocation(`user@domain-${i}.example`), emailAction)
            }
            expect(mockResolveMx).toHaveBeenCalledTimes(MAX_LOCAL_CACHE_DOMAINS + 1)

            // domain-0 was evicted to make room, so it resolves again; a recently
            // inserted domain is still served from the cache.
            await service.getSkipReason(emailInvocation('user@domain-0.example'), emailAction)
            expect(mockResolveMx).toHaveBeenCalledTimes(MAX_LOCAL_CACHE_DOMAINS + 2)
            await service.getSkipReason(emailInvocation(`user@domain-${MAX_LOCAL_CACHE_DOMAINS}.example`), emailAction)
            expect(mockResolveMx).toHaveBeenCalledTimes(MAX_LOCAL_CACHE_DOMAINS + 2)
        })

        it('honors a Valkey-cached verdict without hitting DNS', async () => {
            const valkey: RedisV2 = {
                useClient: jest.fn().mockResolvedValue('0'), // '0' = domain previously found undeliverable
                usePipeline: jest.fn(),
            }
            const withValkey = new EmailValidationService(valkey)

            const reason = await withValkey.getSkipReason(emailInvocation('user@known-dead.example'), emailAction)
            expect(reason).toContain('no reachable mail servers')
            expect(mockResolveMx).not.toHaveBeenCalled()
        })
    })
})

import pytest
from posthog.test.base import BaseTest
from unittest.mock import MagicMock, patch

from temporalio.exceptions import ApplicationError

from posthog.models.integration import Integration

from products.review_hog.backend.reviewer.tools.github_client import GitHubAPIError
from products.review_hog.backend.temporal.activities import (
    RemoveTriggerLabelInput,
    _installation_auth,
    _remove_trigger_label,
)

# The true network boundary: first_for_team_repository probes GitHub with an authenticated
# GET /repos/{repository} per candidate integration row.
_CAN_ACCESS = "posthog.models.integration.github.GitHubIntegration.installation_can_access_repository"


class TestInstallationAuth(BaseTest):
    def _integration(self, installation_id: str = "9876543") -> Integration:
        return Integration.objects.create(
            team=self.team,
            kind="github",
            integration_id=installation_id,
            # No expires_in/refreshed_at → the stored token is used without a refresh round-trip.
            config={},
            sensitive_config={"access_token": "install-tok"},
            created_by=self.user,
        )

    @patch(_CAN_ACCESS, return_value=True)
    def test_returns_the_token_and_the_github_installation_id(self, _can_access: MagicMock) -> None:
        # The egress budget must key on GitHub's installation id (Integration.integration_id), never
        # the PostHog row pk — several rows can share one installation, which has ONE real budget.
        self._integration(installation_id="9876543")

        token, installation_id = _installation_auth(self.team.id, "PostHog/posthog")

        assert token == "install-tok"
        assert installation_id == "9876543"

    @patch(_CAN_ACCESS, return_value=False)
    def test_no_accessible_installation_raises_retryably(self, _can_access: MagicMock) -> None:
        # The probe can't distinguish "no installation" from a transient GitHub failure, so the error
        # must stay retryable; the genuine misconfig fails fast in validate_github_integration_activity.
        self._integration()

        with pytest.raises(ApplicationError) as err:
            _installation_auth(self.team.id, "PostHog/posthog")

        assert err.value.non_retryable is False


class TestRemoveTriggerLabel:
    @patch("products.review_hog.backend.temporal.activities._installation_auth", return_value=("tok", "inst"))
    @patch("products.review_hog.backend.temporal.activities.github_api_request")
    def test_deletes_every_review_label(self, request: MagicMock, _auth: MagicMock) -> None:
        _remove_trigger_label(RemoveTriggerLabelInput(team_id=1, owner="PostHog", repo="posthog", pr_number=7))

        assert [call.args for call in request.call_args_list] == [
            ("DELETE", "/repos/PostHog/posthog/issues/7/labels/posthog-review"),
            ("DELETE", "/repos/PostHog/posthog/issues/7/labels/reviewhog"),
        ]

    @patch("products.review_hog.backend.temporal.activities._installation_auth", return_value=("tok", "inst"))
    @patch(
        "products.review_hog.backend.temporal.activities.github_api_request",
        side_effect=GitHubAPIError("not found", status=404),
    )
    def test_already_removed_label_is_success(self, _request: MagicMock, _auth: MagicMock) -> None:
        _remove_trigger_label(RemoveTriggerLabelInput(team_id=1, owner="PostHog", repo="posthog", pr_number=7))

    @patch("products.review_hog.backend.temporal.activities._installation_auth", return_value=("tok", "inst"))
    @patch(
        "products.review_hog.backend.temporal.activities.github_api_request",
        side_effect=GitHubAPIError("server error", status=500),
    )
    def test_other_github_errors_are_retried(self, _request: MagicMock, _auth: MagicMock) -> None:
        with pytest.raises(GitHubAPIError, match="server error"):
            _remove_trigger_label(RemoveTriggerLabelInput(team_id=1, owner="PostHog", repo="posthog", pr_number=7))
